html:
{% set page_width = "215.9mm" %}
{% set page_height = "279.4mm" %}
{% set label_width = "88.9mm" %}
{% set label_height = "63.5mm" %}
{% set cols = 2 %}
{% set rows = 4 %}
{% set margin_top = "12.7mm" %}
{% set margin_left = "19.05mm" %}
{% set gutter_h = "0mm" %}
{% set gutter_v = "0mm" %}

<style>
    @page {
        size: 215.9mm 279.4mm;
        margin: 0;
    }
    body {
        margin: 0;
        padding: 0;
        font-family: Arial, Helvetica, sans-serif;
    }
    .label-sheet {
        width: 215.9mm;
        height: 279.4mm;
        display: flex;
        flex-direction: column;
        padding: {{ margin_top }};
        margin: 0;
        box-sizing: border-box;
    }
    .label-row {
        display: flex;
        width: 100%;
        height: {{ label_height }};
        margin-bottom: {{ gutter_v }};
    }
    .label-cell {
        width: {{ label_width }};
        height: {{ label_height }};
        box-sizing: border-box;
        position: relative;
        overflow: hidden;
        margin-right: {{ gutter_h }};
    }
    .label-cell:last-child {
        margin-right: 0;
    }
    .label-content {
        position: absolute;
        top: 3mm;
        left: 3mm;
        right: 3mm;
        bottom: 3mm;
        font-size: 6pt;
        line-height: 1.2;
        display: flex;
        flex-direction: column;
        gap: 1mm;
    }
    .label-content .field-label {
        font-weight: bold;
        font-size: 5pt;
        color: #444;
        text-transform: uppercase;
        margin: 0;
        line-height: 1.1;
    }
    .label-content .field-value {
        font-size: 7pt;
        color: #000;
        margin: 0;
        line-height: 1.1;
    }
    .label-content .item-name {
        font-size: 7pt;
        font-weight: bold;
        color: #1a5c2a;
        margin: 0;
    }
    .label-content .customer-name {
        font-size: 7pt;
        font-weight: bold;
        margin: 0;
    }
    .label-content .row {
        display: flex;
        justify-content: space-between;
    }
    .label-content .row .field {
        flex: 1;
    }
    .label-content .row .field:not(:last-child) {
        margin-right: 2mm;
    }
    .position-label {
        position: absolute;
        top: 1mm;
        right: 1mm;
        font-size: 5pt;
        color: #999;
        font-weight: bold;
    }
</style>

