    {# Row 1 #}
    <div class="label-row">
        <div class="label-cell">
            <div class="position-label">A1</div>
            <div class="label-content">
                <div class="customer-name">{{ doc.customer_name or doc.customer }}</div>
                <div class="row">
                    <div class="field"><div class="field-label">SO</div><div class="field-value">{{ doc.name }}</div></div>
                    <div class="field"><div class="field-label">Date</div><div class="field-value">{{ doc.transaction_date }}</div></div>
